{
  "strategy": "Answer the two subgoals directly: use ASR to verify whether dialogue states that Sheldon's brother was a premature baby, and localize the binoculars observation scene to retrieve candidate frames for visual grounding of which hand Dr. Sturgis uses to hold the pot.",
  "tool_calls": [
    {
      "step": 1,
      "tool": "asr",
      "arguments": {
        "video_path": "<VIDEO_PATH>",
        "start_time": null,
