      "depends_on": []
    },
    {
      "step": 2,
      "tool": "temporal_grounder",
      "arguments": {
        "video_path": "<VIDEO_PATH>",
        "query": "Sheldon looking through binoculars and observing Dr. Sturgis holding a pot"
      },
      "purpose": "Localize the visual scene where Sheldon observes Dr. Sturgis through binoculars so the relevant moment can be inspected rather than guessing from the whole video.",
      "depends_on": []
    },
    {
      "step": 3,
      "tool": "frame_retriever",
      "arguments": {
        "video_path": "<VIDEO_PATH>",
        "query": null,
        "timestamps": [
          "<STEP_2:segments[0].start>",
          "<STEP_2:segments[0].end>",
          "<STEP_2:segments[1].start>",
          "<STEP_2:segments[1].end>",
          "<STEP_2:segments[2].start>",
          "<STEP_2:segments[2].end>"
        ],
        "num_frames": 6
      },
      "purpose": "Sample candidate frames from multiple high-confidence temporal-grounder intervals to identify the actual binoculars observation moment and avoid assuming the top-ranked segment is the correct one.",
      "depends_on": [
        2
      ]
    },
    {
      "step": 4,
      "tool": "spatial_grounder",
      "arguments": {
        "frame_path": "<STEP_3:frames>",
        "timestamp": null,
        "query": "Dr. Sturgis holding a pot, with emphasis on which hand is holding the pot"
      },
      "purpose": "Ground Dr. Sturgis and the pot across the candidate frames so the refiner can determine from the per-frame results whether the pot is in his left or right hand.",
      "depends_on": [
        3
      ]
    }
  ],
  "refinement_instructions": "Build the first reasoning trace from scratch. Treat the question as two separate answer-critical claims: (1) which hand Dr. Sturgis is using to hold the pot during the binoculars scene, and (2) whether dialogue indicates Sheldon's brother was a premature baby. For the hand claim, inspect the frame-level outputs from Step 3 and Step 4 together; do not rely on retrieval rank alone. Choose the frame whose timestamp actually matches the binoculars observation scene and cite the spatial grounding evidence about the pot-hand relation there. If Step 4 is only clear on some candidate frames, use those specific frame-level results rather than any top-level summary. For the premature-baby claim, use Step 1 transcript evidence directly; quote or closely paraphrase the relevant dialogue if present, and do not infer from plausibility. Preserve provenance explicitly in the rewritten trace (e.g., ASR shows..., spatial grounding on the binoculars-scene frame shows...). If the new evidence contradicts any option component, update the final answer accordingly. If either subclaim remains ambiguous after these calls, the trace must state that uncertainty instead of forcing an unsupported option."
}
